javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const projectId = event.payload.data.output.data.GlideRecord_Mutation.insert_promin_project.sys_id.value;
    let templateFields;
    const { touchPoints } = api.state;
    const touchPointsResponse = {};
    let touchPointsQuery='';
    if(touchPoints.enabledForProjects) {
        touchPointsResponse.fields = touchPoints.fields.join(',');
        touchPointsResponse.users = touchPoints.users.join(',');
        touchPointsResponse.timeRange = touchPoints.timeRange;
        touchPointsQuery = `^touch_point_fields=${touchPointsResponse.fields}^enable_touch_point=${touchPoints.enabledForProjects}^touch_point_excluded_users=${touchPointsResponse.users}^touch_point_time_range=${touchPointsResponse.timeRange}`;
    }
    const sourceLabel = api.state.selectedSourceLabel.split('(')[0].trim();
    if (api.state.sourceType == 'TABLE') {
        templateFields = `name=${sourceLabel}^table=${api.state.selectedSourceValue}^project=${projectId}^source_type=${api.state.sourceType}${touchPointsQuery}`;
    } else if (api.state.sourceType == 'EXTERNAL_DATA') {
        templateFields = `name=${sourceLabel}^table=${api.state.selectedSourceValue}^project=${projectId}^source_type=${api.state.sourceType}^external_dataset=${api.state.selectedDataSourceID}${touchPointsQuery}`;
    } else if (api.state.sourceType == 'REPORT_SOURCE') {
        templateFields = `name=${sourceLabel}^table=${api.state.selectedSourceValue}^project=${projectId}^source_type=${api.state.sourceType}^report_source=${api.state.selectedDataSourceID}`;
    } else if (api.state.sourceType == 'ARCHIVED_DATA') {
        templateFields = `name=${sourceLabel}^table=${api.state.selectedSourceValue}^project=${projectId}^source_type=${api.state.sourceType}^report_source=${api.state.selectedDataSourceID}${touchPointsQuery}`;
    } else if (api.state.sourceType == 'AGENTIC_AI_DATA') {
        templateFields = `name=${sourceLabel}^table=${api.state.selectedSourceValue}^project=${projectId}^source_type=${api.state.sourceType}^report_source=${api.state.selectedDataSourceID}`;
    }
    return {
        table: "promin_project_entity",
        templateFields: templateFields,
        useSetDisplayValue: null
    };
})

